      out.write("            // Reset form\r\n");
      out.write("            document.querySelector('#addModal form').reset();\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function openEditModal(id, title, description, author, publisher, pubDate,\r\n");
      out.write("                              category, price, stock, imagePath, isActive, discount, featured) {\r\n");
      out.write("            // Populate form fields\r\n");
      out.write("            document.getElementById('editId').value = id;\r\n");
      out.write("            document.getElementById('editTitle').value = title;\r\n");
      out.write("            document.getElementById('editDescription').value = description;\r\n");
      out.write("            document.getElementById('editAuthor').value = author;\r\n");
      out.write("            document.getElementById('editPublisher').value = publisher || '';\r\n");
      out.write("            document.getElementById('editPublicationDate').value = pubDate || '';\r\n");
      out.write("            document.getElementById('editCategory').value = category;\r\n");
      out.write("            document.getElementById('editPrice').value = price;\r\n");
      out.write("            document.getElementById('editStockQuantity').value = stock;\r\n");
      out.write("            document.getElementById('editDiscountPercentage').value = discount;\r\n");
      out.write("            document.getElementById('editIsActive').checked = (isActive === 'true');\r\n");
      out.write("            document.getElementById('editFeatured').checked = (featured === 'true');\r\n");
      out.write("\r\n");
      out.write("            // Display current image\r\n");
      out.write("            const imageContainer = document.getElementById('currentImageContainer');\r\n");
      out.write("            imageContainer.innerHTML = '';\r\n");
      out.write("            if (imagePath && imagePath !== '') {\r\n");
      out.write("                const img = document.createElement('img');\r\n");
      out.write("                const contextPath = '");
      out.print( request.getContextPath() );
      out.write("';\r\n");
      out.write("                const fullPath = imagePath.startsWith('/') ? contextPath + imagePath : contextPath + '/' + imagePath;\r\n");
      out.write("                img.src = fullPath;\r\n");
      out.write("                img.alt = 'Current Product Image';\r\n");
      out.write("                img.className = 'current-image';\r\n");
      out.write("                imageContainer.appendChild(img);\r\n");
      out.write("            } else {\r\n");
      out.write("                imageContainer.innerHTML = '<p style=\"color: rgba(255, 255, 255, 0.7); font-style: italic;\">No current image</p>';\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            document.getElementById('editModal').style.display = 'block';\r\n");
      out.write("            document.body.style.overflow = 'hidden';\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function closeEditModal() {\r\n");
      out.write("            document.getElementById('editModal').style.display = 'none';\r\n");
      out.write("            document.body.style.overflow = 'auto';\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        // Close modal when clicking outside\r\n");
      out.write("        document.getElementById('addModal').onclick = function(event) {\r\n");
      out.write("            if (event.target === this) {\r\n");
      out.write("                closeAddModal();\r\n");
      out.write("            }\r\n");
      out.write("        };\r\n");
      out.write("\r\n");
      out.write("        document.getElementById('editModal').onclick = function(event) {\r\n");
      out.write("            if (event.target === this) {\r\n");
      out.write("                closeEditModal();\r\n");
      out.write("            }\r\n");
      out.write("        };\r\n");
      out.write("\r\n");
      out.write("        // Search/Filter Function\r\n");
      out.write("        function filterTable() {\r\n");
      out.write("            const input = document.getElementById(\"searchInput\");\r\n");
      out.write("            const filter = input.value.toLowerCase().trim();\r\n");
      out.write("            const table = document.getElementById(\"productsTable\");\r\n");
      out.write("            const rows = table.getElementsByTagName(\"tbody\")[0].getElementsByTagName(\"tr\");\r\n");
      out.write("\r\n");
      out.write("            for (let i = 0; i < rows.length; i++) {\r\n");
      out.write("                const titleCell = rows[i].getElementsByTagName(\"td\")[1];\r\n");
      out.write("                const authorCell = rows[i].getElementsByTagName(\"td\")[2];\r\n");
      out.write("                \r\n");
      out.write("                if (titleCell && authorCell) {\r\n");
      out.write("                    const titleText = titleCell.textContent || titleCell.innerText;\r\n");
      out.write("                    const authorText = authorCell.textContent || authorCell.innerText;\r\n");
      out.write("                    \r\n");
      out.write("                    if (titleText.toLowerCase().indexOf(filter) > -1 || \r\n");
      out.write("                        authorText.toLowerCase().indexOf(filter) > -1) {\r\n");
      out.write("                        rows[i].style.display = \"\";\r\n");
      out.write("                    } else {\r\n");
      out.write("                        rows[i].style.display = \"none\";\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        // Close modals with Escape key\r\n");
      out.write("        document.addEventListener('keydown', function(event) {\r\n");
      out.write("            if (event.key === 'Escape') {\r\n");
      out.write("                closeAddModal();\r\n");
      out.write("                closeEditModal();\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Form validation\r\n");
      out.write("        document.addEventListener('DOMContentLoaded', function() {\r\n");
      out.write("            const forms = document.querySelectorAll('form');\r\n");
      out.write("            forms.forEach(form => {\r\n");
      out.write("                form.addEventListener('submit', function(e) {\r\n");
      out.write("                    const requiredFields = form.querySelectorAll('input[required], textarea[required], select[required]');\r\n");
      out.write("                    let isValid = true;\r\n");
      out.write("                    \r\n");
      out.write("                    requiredFields.forEach(field => {\r\n");
      out.write("                        if (!field.value.trim()) {\r\n");
