      out.write("                        e.preventDefault();\r\n");
      out.write("                        alert('⚠️ Please fill in all required fields.');\r\n");
      out.write("                    }\r\n");
      out.write("                });\r\n");
      out.write("            });\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Enhance table interactions\r\n");
      out.write("        document.addEventListener('DOMContentLoaded', function() {\r\n");
      out.write("            const tableRows = document.querySelectorAll('tbody tr');\r\n");
      out.write("            tableRows.forEach(row => {\r\n");
