      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Auto-focus search input with keyboard shortcut\r\n");
      out.write("        document.addEventListener('keydown', function(e) {\r\n");
      out.write("            if (e.ctrlKey && e.key === 'f') {\r\n");
